using PlotterHelper.Geometry;

namespace PlotterHelper.Hatch;

/// <summary>
/// The Gosper curve, "flowsnake": a space-filling curve on a hexagonal lattice, generated by an
/// L-system and fitted to the shape's bounding box.
/// </summary>
/// <remarks>
/// The third texture in the space-filling family. Hilbert and Peano divide a square into 4 or 9, so
/// their detail is rectilinear; the Gosper divides the plane into 7 on a triangular lattice, so its
/// turns are 60 degrees and it reads as flakes rather than stairs.
///
/// <code>
/// A -> A-B--B+A++AA+B-
/// B -> +A-BB--B-A++A+B
/// </code>
/// with + and - as turns of plus and minus 60 degrees, and A and B each one forward step. Order 4 is
/// 2401 steps, which is enough to fill a shape at a readable spacing.
/// </remarks>
internal sealed class GosperFill : IHatchFill
{
    /// <summary>Expansion depth. Length grows 7x per order, so 4 is the practical ceiling.</summary>
    private const int Order = 4;

    private const string ForwardA = "A-B--B+A++AA+B-";
    private const string ForwardB = "+A-BB--B-A++A+B";

    public void Fill(HatchFillContext ctx)
    {
        var opts = ctx.Options;
        double spacing = Math.Max(0.1, Math.Abs(opts.HatchSpacing));

        var curve = CurvePlacement.Fit(Walk(Expand(OrderFor(ctx.BBox, spacing)), spacing), ctx.BBox);
        if (curve.Count < 2) return;

        double startInset = opts.Inset ? Math.Abs(opts.InsetDistance) : 0.0;
        var shapes = HatchGeometry.InsetPolys(ctx.Polygons, startInset, Math.Max(spacing * 0.5, 0.25));
        if (shapes.Count == 0) return;
        var clip = HatchClipper.ToPaths64(shapes, HatchGeometry.Scale);
        if (clip.Count == 0) return;

        foreach (var run in HatchClipper.ClipOpenToPolygon(clip, curve))
            HatchGeometry.AddPolylinePath(ctx.Paths, run);
    }

    /// <summary>
    /// Expansion depth for this element: enough steps that one step is about a spacing apart.
    /// </summary>
    /// <remarks>
    /// Length grows sevenfold per order, so an order offers 7^order steps, and covering the shape's area at
    /// the requested spacing takes about (span/spacing)^2 of them. This was hardcoded at 4, which is right
    /// for a page and far too many for a small element: on a 95-unit icon the curve was fitted down to a
    /// fraction of a spacing and came out as a solid black shape that looked like a broken swatch. Hilbert and
    /// Peano already derive their order from the spacing, so this does the same and leaves a page-sized plot
    /// doing exactly what it did before.
    /// </remarks>
    private static int OrderFor(HatchBBox bbox, double spacing)
    {
        double span = Math.Max(bbox.Xmax - bbox.Xmin, bbox.Ymax - bbox.Ymin);
        double cells = Math.Max(1, span / spacing);
        int order = (int)Math.Ceiling(2 * Math.Log(cells) / Math.Log(7));
        return Math.Clamp(order, 1, Order);
    }

    private static string Expand(int order)
    {
        var current = "A";
        for (int round = 0; round < order; round++)
        {
            var next = new System.Text.StringBuilder(current.Length * 7);
            foreach (char symbol in current)
            {
                switch (symbol)
                {
                    case 'A': next.Append(ForwardA); break;
                    case 'B': next.Append(ForwardB); break;
                    default: next.Append(symbol); break;
                }
            }
            current = next.ToString();
        }
        return current;
    }

    private static List<Vector> Walk(string path, double step)
    {
        var points = new List<Vector>(path.Length);
        // Flat-topped start, so the six directions are the lattice's own.
        double angle = 0;
        double x = 0, y = 0;
        points.Add(new Vector(x, y));

        foreach (char symbol in path)
        {
            switch (symbol)
            {
                case '+': angle += Math.PI / 3; break;
                case '-': angle -= Math.PI / 3; break;
                case 'A':
                case 'B':
                    x += step * Math.Cos(angle);
                    y += step * Math.Sin(angle);
                    points.Add(new Vector(x, y));
                    break;
            }
        }
        return points;
    }
}
